const knownTagSlugs = new Set(
  tagGroups.flatMap((group) => group.tags.map((tag) => tag.slug))
);

function normalizeTagSlugs(slugs) {
  return [...new Set(slugs.filter(Boolean))].filter((slug) => knownTagSlugs.has(slug));
}

function uniqueStrings(values) {
  return [...new Set(values.filter(Boolean).map((value) => String(value).trim()).filter(Boolean))];
}

function rawCardTagSlugs(card) {
  const values = Array.isArray(card.tagSlugs)
    ? card.tagSlugs
    : Array.isArray(card.tags)
      ? card.tags
      : [];
  return values.map((tag) => (typeof tag === "string" ? tag : tag.slug)).filter(Boolean);
}

function nodeTagSlugs({ axis, key, categorySlug }) {
  const axisTags =
    axis === "thought" ? ["life-question"] : axis === "debate" ? ["ethics"] : [];
  const categoryTags = axis === "worry" ? categoryTagMap[categorySlug] || [] : [];
  return normalizeTagSlugs([...axisTags, ...categoryTags, ...(nodeTagMap[key] || [])]);
}

function tagsForContent(content, context) {
  const baseTagSlugs = nodeTagSlugs(context);
  const sourceLocaleInsights = sourceLocaleInsightsForKey(context.key);
  const sourceLocaleSignal = sourceLocaleSignalForKey(context.key);
  const sourceLocaleDoors = sourceLocaleUserDoorsForKey(context.key);
  const enrichedContent = {
    ...content,
    doors: uniqueStrings([...(content.doors || []), ...sourceLocaleDoors]),
  };
  const cards = (content.cards || []).map((rawCard) => {
    const card = withSourceMetadata(rawCard);
    const cardTagSlugs = normalizeTagSlugs([
      ...baseTagSlugs,
      ...rawCardTagSlugs(card),
      ...(thinkerTagMap[card.name] || []),
    ]);
    return {
      ...card,
      tagSlugs: cardTagSlugs,
      tags: tagsFromSlugs(cardTagSlugs),
    };
  });

  return {
    ...enrichedContent,
    sourceLocaleInsights,
    sourceLocaleSignal,
    tagSlugs: baseTagSlugs,
    tags: tagsFromSlugs(baseTagSlugs),
    tagGroups: groupedTagsFromSlugs(baseTagSlugs),
    cards,
  };
}

// ── 헬퍼 ────────────────────────────────────────────────────────────────────
const tagProfileMap = {
  anxiety: {
    intro:
      "불안은 아직 오지 않은 일이 현재의 몸과 마음을 먼저 점령할 때 커진다. 위즈덤에서는 불안을 없애야 할 결함으로만 보지 않고, 통제 가능한 행동과 통제 불가능한 결과를 나누는 신호로 다룬다.",
  },
  emptiness: {
    intro:
      "공허는 아무것도 없어서라기보다, 하던 일과 욕망이 더 이상 나를 설득하지 못할 때 자주 올라온다. 이 태그는 번아웃, 삶의 의미, 좋은 삶의 질문을 함께 묶어 다시 기준을 세우게 한다.",
  },
  pressure: {
    intro:
      "압박감은 해야 할 일, 남의 기대, 자기 증명이 한꺼번에 몰릴 때 생긴다. 여기서는 더 세게 밀어붙이는 법보다, 기준을 줄이고 지속 가능한 행동 단위로 낮추는 관점을 모은다.",
  },
  control: {
    intro:
      "통제 불가는 위즈덤의 핵심 태그다. 상대의 마음, 시험 결과, 평판, 미래처럼 내 뜻대로 되지 않는 것에서 마음을 떼고, 내가 실제로 선택할 수 있는 행동으로 돌아가는 카드들이 모인다.",
  },
};

export function allTags() {
  return tagGroups.flatMap((group) =>
    group.tags.map((tag) => ({
      ...tag,
      ...(tagProfileMap[tag.slug] || {}),
      groupSlug: group.slug,
      groupTitle: group.title,
    }))
  );
}

export function getTag(slug) {
  return allTags().find((tag) => tag.slug === slug) || null;
}

export function tagsFromSlugs(slugs) {
  return normalizeTagSlugs(slugs).map((slug) => getTag(slug)).filter(Boolean);
}

export function groupedTagsFromSlugs(slugs) {
  const tagSet = new Set(normalizeTagSlugs(slugs));
  return tagGroups
    .map((group) => ({
      ...group,
      tags: group.tags.filter((tag) => tagSet.has(tag.slug)),
    }))
    .filter((group) => group.tags.length > 0);
}

export function getCategory(categorySlug) {
  return categories.find((c) => c.slug === categorySlug) || null;
}

export function getWorry(categorySlug, worrySlug) {
  const cat = getCategory(categorySlug);
  if (!cat) return null;
  return cat.worries.find((w) => w.slug === worrySlug) || null;
}

export function getWorryGroup(categorySlug) {
  return worryGroups.find((group) => group.categorySlugs.includes(categorySlug)) || null;
}

export function groupedWorryCategories() {
  return worryGroups.map((group) => ({
    ...group,
    categories: group.categorySlugs.map((slug) => getCategory(slug)).filter(Boolean),
  }));
}

// 상세 콘텐츠. 실제 데이터가 없으면 placeholder:true 로 반환(정직하게 '준비 중' 표시).
export function getContent(categorySlug, worrySlug) {
  const key = `${categorySlug}/${worrySlug}`;
  const context = { axis: "worry", key, categorySlug };
  if (worryContent[key]) {
    return tagsForContent({ doors: [], ...worryContent[key], placeholder: false }, context);
  }
  return tagsForContent(
    { emotion: null, doors: [], cards: [], actions: [], placeholder: true },
    context
  );
}

export function verifiedCardCount(content) {
  return (content.cards || []).filter((card) => card.verified).length;
}

export function isPublishableContent(content) {
  if (!content || content.placeholder) return false;
  return verifiedCardCount(content) >= 2;
}

export function allWorryEntries() {
  return categories.flatMap((category) =>
    category.worries.map((worry) => {
      const content = getContent(category.slug, worry.slug);
      return {
        axis: "worry",
        key: `${category.slug}/${worry.slug}`,
        href: `/${category.slug}/${worry.slug}`,
        title: worry.title,
        categoryTitle: category.title,
        groupTitle: getWorryGroup(category.slug)?.title || null,
        summary: content.emotion || category.blurb,
        tagSlugs: content.tagSlugs || [],
        tags: content.tags || [],
        content,
        verifiedCount: verifiedCardCount(content),
        publishable: isPublishableContent(content),
      };
    })
  );
}

// 빌드/라우팅용: 모든 (category, worry) 조합
export function allWorryParams() {
  const params = [];
  for (const cat of categories) {
    for (const w of cat.worries) {
      params.push({ category: cat.slug, worry: w.slug });
    }
  }
  return params;
}

// ── 논쟁 헬퍼 ───────────────────────────────────────────────────────────────
export function getDebate(slug) {
  return debates.find((d) => d.slug === slug) || null;
}

export function getDebateGroup(slug) {
  return debateGroups.find((group) => group.debateSlugs.includes(slug)) || null;
}

export function groupedDebates() {
  return debateGroups.map((group) => ({
    ...group,
    debates: group.debateSlugs.map((slug) => getDebate(slug)).filter(Boolean),
  }));
}

export function getDebateContent(slug) {
  const context = { axis: "debate", key: `debate/${slug}` };
  if (debateContent[slug]) {
    return tagsForContent({ ...debateContent[slug], placeholder: false }, context);
  }
  const d = getDebate(slug);
  return tagsForContent(
    { question: d?.question || null, doors: [], cards: [], reflect: [], placeholder: true },
    context
  );
}

export function allDebateParams() {
  return debates.map((d) => ({ slug: d.slug }));
}

export function allDebateEntries() {
  return debates.map((debate) => {
    const content = getDebateContent(debate.slug);
    return {
      axis: "debate",
      key: `debate/${debate.slug}`,
      href: `/debate/${debate.slug}`,
      title: debate.question,
      categoryTitle: "논쟁",
      groupTitle: getDebateGroup(debate.slug)?.title || null,
      summary: debate.blurb,
      tagSlugs: content.tagSlugs || [],
      tags: content.tags || [],
      content,
      verifiedCount: verifiedCardCount(content),
      publishable: isPublishableContent(content),
    };
  });
}

// ── 생각 헬퍼 ───────────────────────────────────────────────────────────────
export function getThought(slug) {
  return thoughts.find((thought) => thought.slug === slug) || null;
}

export function getThoughtGroup(slug) {
  return thoughtGroups.find((group) => group.thoughtSlugs.includes(slug)) || null;
}

export function groupedThoughts() {
  return thoughtGroups.map((group) => ({
    ...group,
    thoughts: group.thoughtSlugs.map((slug) => getThought(slug)).filter(Boolean),
  }));
}

export function getThoughtContent(slug) {
  const context = { axis: "thought", key: `thought/${slug}` };
  if (thoughtContent[slug]) {
    return tagsForContent({ doors: [], ...thoughtContent[slug], placeholder: false }, context);
  }
  const thought = getThought(slug);
  return tagsForContent(
    {
      question: thought?.question || null,
      doors: [],
      cards: [],
      reflect: [],
      placeholder: true,
    },
    context
  );
}

export function allThoughtParams() {
  return thoughts.map((thought) => ({ slug: thought.slug }));
}

export function allThoughtEntries() {
  return thoughts.map((thought) => {
    const content = getThoughtContent(thought.slug);
    return {
      axis: "thought",
      key: `thought/${thought.slug}`,
      href: `/thought/${thought.slug}`,
      title: thought.question,
      categoryTitle: "생각",
      groupTitle: getThoughtGroup(thought.slug)?.title || null,
      summary: thought.blurb,
      tagSlugs: content.tagSlugs || [],
      tags: content.tags || [],
      content,
      verifiedCount: verifiedCardCount(content),
      publishable: isPublishableContent(content),
    };
  });
}

let cachedContentEntries = null;

export function allContentEntries() {
  if (!cachedContentEntries) {
    cachedContentEntries = [...allWorryEntries(), ...allThoughtEntries(), ...allDebateEntries()];
  }
  return cachedContentEntries;
}

export function entriesForTag(slug) {
  return allContentEntries().filter((entry) => entry.tagSlugs.includes(slug));
}

export function cardsForTag(slug) {
  return entriesForTag(slug)
    .filter((entry) => entry.publishable)
    .flatMap((entry) =>
      (entry.content.cards || [])
        .filter((card) => card.tagSlugs?.includes(slug))
        .map((card) => ({ entry, card }))
    );
}

export function groupedTagsWithCounts() {
  const publishableEntries = allContentEntries().filter((entry) => entry.publishable);
  const cards = publishableEntries.flatMap((entry) =>
    (entry.content.cards || []).map((card) => ({ entry, card }))
  );

  return tagGroups
    .map((group) => ({
      ...group,
      tags: group.tags
        .map((tag) => ({
          ...tag,
          entryCount: publishableEntries.filter((entry) =>
            entry.tagSlugs.includes(tag.slug)
          ).length,
          cardCount: cards.filter(({ card }) => card.tagSlugs?.includes(tag.slug)).length,
        }))
        .filter((tag) => tag.entryCount > 0 || tag.cardCount > 0),
    }))
    .filter((group) => group.tags.length > 0);
}

export function allTagParams() {
  return allTags().map((tag) => ({ slug: tag.slug }));
}

