function normalizePersonName(name) {
  return personNameAliases[name] || name;
}

function slugForPersonName(name) {
  const normalized = normalizePersonName(name);
  if (personSlugMap[normalized]) return personSlugMap[normalized];
  return normalized
    .toLowerCase()
    .replace(/[^a-z0-9가-힣]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

let cachedPeople = null;

export function allPeople() {
  if (cachedPeople) return cachedPeople;

  const people = new Map();
  const entries = allContentEntries().filter((entry) => entry.publishable);

  for (const entry of entries) {
    for (const card of entry.content.cards || []) {
      if (!card.name || nonPersonCardNames.has(card.name)) continue;

      const name = normalizePersonName(card.name);
      const slug = slugForPersonName(name);
      if (!people.has(slug)) {
        const culture = personCultureProfile(slug, name);
        people.set(slug, {
          slug,
          name,
          role: card.role,
          culture,
          cards: [],
          entries: new Map(),
          tagSlugs: new Set(),
        });
      }

      const person = people.get(slug);
      person.cards.push({ entry, card: { ...card, name, personCulture: person.culture } });
      person.entries.set(entry.key, entry);
      for (const tagSlug of card.tagSlugs || entry.tagSlugs || []) {
        person.tagSlugs.add(tagSlug);
      }
    }
  }

  cachedPeople = [...people.values()]
    .map((person) => ({
      slug: person.slug,
      name: person.name,
      role: person.role,
      summary:
        personProfileMap[person.slug]?.summary ||
        `${person.name}의 관점이 등장하는 고민·생각·논쟁 카드 모음.`,
      intro:
        personProfileMap[person.slug]?.intro ||
        `${person.name}의 카드를 관련 페이지와 함께 모았다. 어떤 상황에서 이 관점이 반복해서 쓰이는지 확인할 수 있다.`,
      culture: person.culture,
      cardCount: person.cards.length,
      entryCount: person.entries.size,
      cards: person.cards,
      entries: [...person.entries.values()],
      tags: tagsFromSlugs([...person.tagSlugs]).slice(0, 8),
    }))
    .sort((a, b) => b.cardCount - a.cardCount || a.name.localeCompare(b.name, "ko"));

  return cachedPeople;
}

export function getPerson(slug) {
  return allPeople().find((person) => person.slug === slug) || null;
}

export function allPersonParams() {
  return allPeople().map((person) => ({ slug: person.slug }));
}

export function getEntryByKey(key) {
  return allContentEntries().find((entry) => entry.key === key) || null;
}

export function peopleForEntryKey(key) {
  const entry = getEntryByKey(key);
  if (!entry) return [];

  const people = new Map();
  for (const card of entry.content.cards || []) {
    if (!card.name || nonPersonCardNames.has(card.name)) continue;
    const name = normalizePersonName(card.name);
    const person = getPerson(slugForPersonName(name));
    if (person) people.set(person.slug, person);
  }
  return [...people.values()];
}

export function relatedEntriesForKey(key, limit = 4) {
  const current = getEntryByKey(key);
  if (!current) return [];

  const currentTags = new Set(current.tagSlugs || []);
  const currentPeople = new Set(peopleForEntryKey(key).map((person) => person.slug));

  return allContentEntries()
    .filter((entry) => entry.publishable && entry.key !== key)
    .map((entry) => {
      const tagScore = (entry.tagSlugs || []).filter((slug) => currentTags.has(slug)).length;
      const peopleScore = peopleForEntryKey(entry.key).filter((person) =>
        currentPeople.has(person.slug)
      ).length;
      const groupScore = entry.groupTitle && entry.groupTitle === current.groupTitle ? 1 : 0;
      return {
        entry,
        score: tagScore * 3 + peopleScore * 4 + groupScore,
      };
    })
    .filter((item) => item.score > 0)
    .sort((a, b) => b.score - a.score || b.entry.verifiedCount - a.entry.verifiedCount)
    .slice(0, limit)
    .map((item) => item.entry);
}

