function positionForDebateCard(debateSlug, card) {
  const mapped = debateCardPositionMap[`${debateSlug}/${card.name}`];
  if (mapped) return mapped;

  const text = `${card.stance || ""} ${card.view || ""}`;
  if (/사실|현행|기준|정리/.test(text)) return "context";
  if (/폐지|금지|불가|반대|신중|차별/.test(text)) return "oppose";
  if (/유지|허용|정당|옹호|응보/.test(text)) return "support";
  return "conditional";
}

export function debatePositionSections() {
  const hits = allDebateEntries()
    .filter((entry) => entry.publishable)
    .flatMap((entry) =>
      (entry.content.cards || []).map((card) => {
        const debateSlug = entry.key.replace("debate/", "");
        return {
          entry,
          card,
          position: positionForDebateCard(debateSlug, card),
        };
      })
    );

  return debatePositionGroups.map((group) => ({
    ...group,
    hits: hits.filter((hit) => hit.position === group.slug),
  }));
}

export function debatePositionSummary(slug) {
  const content = getDebateContent(slug);
  if (!content || content.placeholder) return [];

  const groupBySlug = new Map(debatePositionGroups.map((group) => [group.slug, group]));
  return (content.cards || []).map((card) => {
    const position = positionForDebateCard(slug, card);
    const group = groupBySlug.get(position);
    return {
      name: card.name,
      role: card.role,
      stance: card.stance,
      position,
      positionTitle: group?.title || "조건부 / 절충",
    };
  });
}
